def bootstrap_mean(values, repeats=2000, seed=7):
    values = np.asarray(values, float).reshape(-1)
    if values.size < 2 or repeats < 10:
        raise ValueError("need at least two values and ten repeats")
    rng = np.random.default_rng(seed)
    samples = rng.choice(values, size=(repeats, values.size), replace=True)
    means = samples.mean(axis=1)
    return float(np.quantile(means, 0.025)), float(np.quantile(means, 0.975))

low, high = bootstrap_mean([0.9, 1.0, 1.1, 1.2])
assert low <= 1.05 <= high
